head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil52500";
scwin.form = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — isOk, loadTp

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil52500.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String((dma_pageContext.get("totalCountIntValue") ?? "")) + "건 [" + String((dma_pageContext.get("currentPage") ?? "")) + "/" + String((dma_pageContext.get("totalPageCount") ?? "")) + "Page]"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.prelistPageForm || { elements: [] });
        await scwin.defaultCheck();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil52500.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(nwlistforncomanlrpt#getnwlistforncomanlrptlist vs nwlistforncomanlrpt#submitrpt) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_clmSchdlNoti_oncellclick
 * @description grd_clmSchdlNoti 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_clmSchdlNoti_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_clmSchdlNoti');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_clmSchdlNoti */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["listProcsStatCd"] === '33'|| r["listProcsStatCd"] === '36') { await scwin.openAdjReqPopNw(r["bzProcsNo"], "170", "75"); return; } if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { await scwin.submitRpt(r["bzProcsNo"], "75"); return; } return; } if (r["listProcsStatCd"] !== '30' && r["listProcsStatCd"] !== '37' && r["listProcsStatCd"] !== '35') { await scwin.viewDetail(r["bzProcsNo"], r["seq"]); return; }
        if (r["listProcsStatCd"] === '30') { await scwin.viewDetail(r["bzProcsNo"], r["seq"]); return; }
        if (r["listProcsStatCd"] === '35') { await scwin.viewDetail(r["bzProcsNo"], r["seq"]); return; }
        if (r["listProcsStatCd"] === '37') { await scwin.viewDetail(r["bzProcsNo"], r["seq"]); return; }
        await scwin.viewDetail(r["bzProcsNo"], r["seq"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_clmSchdlNoti.oncellclick' });
    }
};

/**
 * @method
 * @name btn_newWrite_onclick
 * @description 「신규작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_newWrite_onclick = function(e){
    try {
        scwin.newWrite()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52500.btn_newWrite_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_63_onclick
 * @description krxpage_pagenavigator_63 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_63_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_63.page' }); } await scwin.fncSearch(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_viewDetail
 * @description view Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/listInvstg/nwlistForncomAnlrpt.do",
        ref: "dma_viewDetailReq",
        target: "dlt_clmSchdlNoti=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/listInvstg/nwlistForncomAnlrpt.do?method=getNwlistForncomAnlrptList",
        ref: "dma_searchCorpListByBeginIndexReq",
        target: "dlt_clmSchdlNoti=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_submitRpt
 * @description submit Rpt 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_submitRpt = async function () {
    const sbmOptions = {
        id: "tx_submitRpt",
        method: "post",
        action: "/listInvstg/nwlistForncomAnlrpt.do?method=submitRpt",
        ref: "dma_submitRptReq",
        target: "dlt_clmSchdlNoti=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_clmSchdlNoti_fillAct
 * @description grd clm Schdl Noti fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_clmSchdlNoti_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_clmSchdlNoti');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) { if (r["listProcsStatCd"] === '33'|| r["listProcsStatCd"] === '36') { v = "수정요청"; } else if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { v = "제출"; } }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_clmSchdlNoti.fillAct' });
    }
};

/**
 * @method
 * @name viewDetail
 * @description view Detail 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} seq seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewDetail = async function (bzProcsNo, seq) {
    $c.util.getComponent('dma_viewDetailReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_viewDetailReq').set('seq', seq);
    scwin.form.action = '/listInvstg/nwlistForncomAnlrpt.do';
    $c.util.getComponent('dma_viewDetailReq').set('method', 'editForm');
    await scwin.tx_viewDetail();
};

/**
 * @method
 * @name newWrite
 * @description new Write 처리
 * @returns {void}
 * @hidden N
 */
scwin.newWrite = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil52510/jldfil52510.xml');
};

/**
 * @method
 * @name defaultCheck
 * @description default Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.defaultCheck = async function () {
    const isOk = (String(((dma_pageContext.get("isOk") ?? "")) === null ? '' : ((dma_pageContext.get("isOk") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("isOk") ?? "")) === null ? '' : ((dma_pageContext.get("isOk") ?? ""))));
    const loadTp = (String(((dma_pageContext.get("loadTp") ?? "")) === null ? '' : ((dma_pageContext.get("loadTp") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("loadTp") ?? "")) === null ? '' : ((dma_pageContext.get("loadTp") ?? ""))));
    if (loadTp === '4') {
        if (isOk) {
            await $c.win.alert('삭제되었습니다.');
        } else {
            await $c.win.alert('삭제시 오류가 발생 되었습니다.');
        }
    } else {
        if (isOk !== '') {
            if (isOk) {
                await $c.win.alert('제출되었습니다');
            } else {
                await $c.win.alert('제출시 오류가 발생했습니다.');
            }
            await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /jldfil52510/jldfil52510.xml?method=getNwlistForncomAnlrptList&pageIndex=). 전환 대상 화면이 확정되면 연결됩니다.') + null;
        }
    }
};

/**
 * @method
 * @name fncSearch
 * @description fnc Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fncSearch = async function () {
    const pageIndex = $c.util.getComponent('dma_viewDetailReq').get('pageIndex');
    $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pageIndex);
    await scwin.searchCorpListByBeginIndex();
};

/**
 * @method
 * @name searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpListByBeginIndex = async function () {
    scwin.form.action = '/listInvstg/nwlistForncomAnlrpt.do?method=getNwlistForncomAnlrptList';
    await scwin.tx_searchCorpListByBeginIndex();
};

/**
 * @method
 * @name submitRpt
 * @description submit Rpt 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} listBzDtlTpCd listBzDtlTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submitRpt = async function (bzProcsNo, listBzDtlTpCd) {
    scwin.form.action = "/listInvstg/nwlistForncomAnlrpt.do?method=submitRpt";
    $c.util.getComponent('dma_viewDetailReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_viewDetailReq').set('listBzDtlTpCd', listBzDtlTpCd);
    if (await $c.win.confirm('제출하시겠습니까?')) {
        await scwin.tx_submitRpt();
    }
};

/**
 * @method
 * @name openAdjReqPopNw
 * @description open Adj Req Pop Nw 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} listInvstgBzTpCd listInvstgBzTpCd
 * @param {String} listBzDtlTpCd listBzDtlTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openAdjReqPopNw = async function (bzProcsNo, listInvstgBzTpCd, listBzDtlTpCd) {
    w = '500';
    h = '250';
    l = screen.width / 2 - w / 2;
    t = screen.height / 2 - h / 2;
    const corpSearchURL = '/jldfil52510/jldfil52510.xml';
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { const __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(corpSearchURL), { id: "popup4adjReq", scrollbars: false, resizable: false, width: "500", height: "250", type: "pageFramePopup" }, { method: "selectAvailableAdjReq", bzProcsNo: bzProcsNo, listInvstgBzTpCd: listInvstgBzTpCd, listBzDtlTpCd: listBzDtlTpCd });
};
